// file: main.go
package main

import "fmt"

// version is set at build time via -ldflags "-X main.version=..."
// It defaults to "dev" for local builds.
var version = "dev"

func main() {
	fmt.Printf("app version: %s\n", version)
}

/*
Build a release binary stamped with the current git commit, with local paths
stripped (-trimpath) for reproducibility, and CGO disabled for a static binary:

    CGO_ENABLED=0 go build -trimpath \
        -ldflags "-s -w -X main.version=$(git rev-parse --short HEAD)" \
        -o bin/app .

Cross-compile the same for Linux from any host:

    CGO_ENABLED=0 GOOS=linux GOARCH=amd64 go build \
        -ldflags "-X main.version=$(git rev-parse --short HEAD)" -o bin/app-linux .
*/
